1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge is visible to other
7	// callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/bits"
14		"sync"
15		"sync/atomic"
16		"time"
17	)
18	
19	// ErrOutOfOrder is returned by Add when a sample predates the most recent
20	// sample the roller has already accepted.
21	var ErrOutOfOrder = errors.New("rollup: out of order")
22	
23	// ErrWindowMismatch is returned by Merge when the two rollers use different
24	// window sizes.
25	var ErrWindowMismatch = errors.New("rollup: window mismatch")
26	
27	// Window holds the aggregate statistics of the samples filed into one
28	// window. Start is the window's left-closed, right-open lower bound.
29	type Window struct {
30		Start time.Time
31		Count int64
32		Sum   float64
33		Min   float64
34		Max   float64
35	}
36	
37	// Roller aggregates samples into fixed windows of a single size.
38	//
39	// The zero value is not usable; build one with New. All methods are safe
40	// to call concurrently from multiple goroutines.
41	type Roller struct {
42		// mu guards buckets, back, latest, and hasAny. window and id are
43		// fixed at construction and read without the lock.
44		//
45		// buckets is one flat slice kept sorted by window start: samples
46		// arrive in non-decreasing time order, so Add appends in amortized
47		// constant time, Windows reads out without re-sorting, and Merge is
48		// a single linear pass over both sides.
49		//
50		// back is a second sorted slice holding backfilled windows: a sample
51		// that lands before the newest window opens its bucket here, so the
52		// insert never shifts the tail of buckets and mass backfills stay
53		// cheap. back is folded into buckets once it is large enough for
54		// the merge to amortize. Every read consults both slices, and no
55		// window start appears in both at the same time.
56		mu      sync.RWMutex
57		id      uint64
58		window  time.Duration
59		buckets []Window
60		back    []Window
61		latest  time.Time
62		hasAny  bool
63	}
64	
65	// idGen hands out unique roller IDs so Merge can lock two rollers in a
66	// consistent order and concurrent cross-merges cannot deadlock.
67	var idGen atomic.Uint64
68	
69	// New builds a roller with the given window size. It panics with
70	// "rollup: bad window" if window is not positive.
71	func New(window time.Duration) *Roller {
72		if window <= 0 {
73			panic("rollup: bad window")
74		}
75		return &Roller{
76			id:     idGen.Add(1),
77			window: window,
78		}
79	}
80	
81	// startOf returns the start of the window containing at, aligned to an
82	// integer multiple of the window size since the Unix epoch. The arithmetic
83	// is exact for any time value, including ones whose nanosecond offset from
84	// the epoch does not fit in an int64.
85	func (r *Roller) startOf(at time.Time) time.Time {
86		sec := at.Unix()
87		nsec := int64(at.Nanosecond())
88		w := r.window.Nanoseconds()
89		if sec >= -9223372036 && sec <= 9223372035 {
90			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
91			// a window multiple can reach ns-(w-1), so stay on the fast
92			// path only when that product cannot overflow either.
93			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
94				start := ns / w
95				if ns%w != 0 && ns < 0 {
96					start--
97				}
98				return time.Unix(0, start*w).UTC()
99			}
100		}
101		return windowStartWide(sec, nsec, w)
102	}
103	
104	// windowStartWide is the 128-bit slow path of startOf, for times whose
105	// nanosecond offset from the epoch overflows an int64.
106	func windowStartWide(sec, nsec, w int64) time.Time {
107		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
108		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
109		if sec < 0 {
110			uhi -= 1e9
111		}
112		hi := int64(uhi)
113		lo := ulo + uint64(nsec)
114		if lo < ulo {
115			hi++
116		}
117		// Round t down to a multiple of w: start = t - floorMod(t, w).
118		rem := floorMod128(hi, lo, w)
119		if lo < rem {
120			hi--
121		}
122		lo -= rem
123		// Split start into whole seconds and nanoseconds.
124		ns := floorMod128(hi, lo, 1e9)
125		if lo < ns {
126			hi--
127		}
128		lo -= ns
129		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
130	}
131	
132	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
133	// and positive y, with the result in [0, y).
134	func floorMod128(hi int64, lo uint64, y int64) uint64 {
135		yu := uint64(y)
136		if hi >= 0 {
137			return rem128(uint64(hi), lo, yu)
138		}
139		// Negate the 128-bit value, take the remainder, and reflect it back
140		// into [0, y) for floored (not truncated) division.
141		mlo := -lo
142		mhi := -uint64(hi)
143		if lo != 0 {
144			mhi--
145		}
146		if r := rem128(mhi, mlo, yu); r != 0 {
147			return yu - r
148		}
149		return 0
150	}
151	
152	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
153	// exact multiple of y, with a quotient that fits in an int64.
154	func quo128(hi int64, lo uint64, y int64) int64 {
155		yu := uint64(y)
156		if hi >= 0 {
157			q, _ := bits.Div64(uint64(hi), lo, yu)
158			return int64(q)
159		}
160		mlo := -lo
161		mhi := -uint64(hi)
162		if lo != 0 {
163			mhi--
164		}
165		q, _ := bits.Div64(mhi, mlo, yu)
166		return -int64(q)
167	}
168	
169	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
170	func rem128(hi, lo, y uint64) uint64 {
171		if hi >= y {
172			hi %= y
173		}
174		return bits.Rem64(hi, lo, y)
175	}
176	
177	// windowIndex locates the window starting at start in ws, which must be
178	// sorted by window start. The second result reports whether it exists;
179	// when it does not, the index is where it would be inserted to keep ws
180	// sorted, i.e. the first window whose start is not before start.
181	func windowIndex(ws []Window, start time.Time) (int, bool) {
182		sec, nsec := start.Unix(), int64(start.Nanosecond())
183		lo, hi := 0, len(ws)
184		for lo < hi {
185			mid := int(uint(lo+hi) >> 1)
186			s := ws[mid].Start
187			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
188				lo = mid + 1
189			} else {
190				hi = mid
191			}
192		}
193		if lo < len(ws) {
194			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
195				return lo, true
196			}
197		}
198		return lo, false
199	}
200	
201	// addTo folds one sample into w. Count saturates at math.MaxInt64 instead
202	// of overflowing; Sum, Min, and Max keep updating afterwards.
203	func addTo(w *Window, value float64) {
204		if w.Count < math.MaxInt64 {
205			w.Count++
206		}
207		w.Sum += value
208		if value < w.Min {
209			w.Min = value
210		}
211		if value > w.Max {
212			w.Max = value
213		}
214	}
215	
216	// Add files a sample into its window. A sample earlier than the most recent
217	// accepted sample is rejected with ErrOutOfOrder and leaves the roller
218	// unchanged; a sample at the same instant is accepted and counted again.
219	//
220	// Concurrent Adds are serialized: each takes effect in the order it
221	// acquires the roller, and the out-of-order check is measured against the
222	// samples accepted before it in that order.
223	func (r *Roller) Add(at time.Time, value float64) error {
224		r.mu.Lock()
225		defer r.mu.Unlock()
226		if r.hasAny && at.Before(r.latest) {
227			return ErrOutOfOrder
228		}
229		start := r.startOf(at)
230		n := len(r.buckets)
231		switch {
232		case n == 0:
233			r.buckets = append(r.buckets, newBucket(start, value))
234		case !start.Before(r.buckets[n-1].Start):
235			// The common case: the sample lands in the newest window or
236			// just past it, so the sorted order is maintained for free.
237			if r.buckets[n-1].Start.Equal(start) {
238				addTo(&r.buckets[n-1], value)
239			} else {
240				r.buckets = append(r.buckets, newBucket(start, value))
241			}
242		default:
243			// The sample belongs to an older window, which can only happen
244			// after a merge brought in windows past latest. A window that
245			// already exists is updated in place; a new one goes into the
246			// backfill buffer, so inserting it never shifts the tail of
247			// buckets and the cost of a mass backfill does not grow with
248			// the number of windows already accepted.
249			if i, ok := windowIndex(r.buckets, start); ok {
250				addTo(&r.buckets[i], value)
251			} else if i, ok := windowIndex(r.back, start); ok {
252				addTo(&r.back[i], value)
253			} else {
254				r.back = append(r.back, Window{})
255				copy(r.back[i+1:], r.back[i:])
256				r.back[i] = newBucket(start, value)
257				r.maybeFlushBack()
258			}
259		}
260		r.latest = at
261		r.hasAny = true
262		return nil
263	}
264	
265	// newBucket returns a window holding a single sample.
266	func newBucket(start time.Time, value float64) Window {
267		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
268	}
269	
270	// maybeFlushBack folds the backfill buffer into buckets once it holds at
271	// least half as many windows, so the merge cost amortizes to constant
272	// time per backfilled window. The caller must hold mu.
273	func (r *Roller) maybeFlushBack() {
274		if len(r.back)*2 >= len(r.buckets) {
275			r.buckets = mergeWindows(r.buckets, r.back)
276			r.back = nil
277		}
278	}
279	
280	// mergeWindows returns the sorted union of two window slices, each sorted
281	// by window start, combining the statistics of windows that share a
282	// start: counts and sums add, minimums take the smaller, maximums take
283	// the larger. The result is always a fresh slice.
284	func mergeWindows(a, b []Window) []Window {
285		merged := make([]Window, 0, len(a)+len(b))
286		i, j := 0, 0
287		for i < len(a) && j < len(b) {
288			switch {
289			case a[i].Start.Before(b[j].Start):
290				merged = append(merged, a[i])
291				i++
292			case b[j].Start.Before(a[i].Start):
293				merged = append(merged, b[j])
294				j++
295			default:
296				w := a[i]
297				w.Count = satAdd(w.Count, b[j].Count)
298				w.Sum += b[j].Sum
299				if b[j].Min < w.Min {
300					w.Min = b[j].Min
301				}
302				if b[j].Max > w.Max {
303					w.Max = b[j].Max
304				}
305				merged = append(merged, w)
306				i++
307				j++
308			}
309		}
310		merged = append(merged, a[i:]...)
311		merged = append(merged, b[j:]...)
312		return merged
313	}
314	
315	// Window returns the bucket whose start matches start exactly. The second
316	// result is false when no bucket starts at that instant; no nearby bucket
317	// is substituted. The returned Window is a copy and stays valid no matter
318	// what is filed afterwards.
319	func (r *Roller) Window(start time.Time) (Window, bool) {
320		r.mu.RLock()
321		defer r.mu.RUnlock()
322		if i, ok := windowIndex(r.buckets, start); ok {
323			return r.buckets[i], true
324		}
325		if i, ok := windowIndex(r.back, start); ok {
326			return r.back[i], true
327		}
328		return Window{}, false
329	}
330	
331	// Windows returns all buckets in time order. An empty roller yields an
332	// empty slice. The result is a snapshot of one moment: samples filed after
333	// the call do not alter it.
334	func (r *Roller) Windows() []Window {
335		r.mu.RLock()
336		defer r.mu.RUnlock()
337		if len(r.back) != 0 {
338			return mergeWindows(r.buckets, r.back)
339		}
340		out := make([]Window, len(r.buckets))
341		copy(out, r.buckets)
342		return out
343	}
344	
345	// Range returns the buckets that overlap the half-open interval
346	// [from, to), in time order. The endpoints are attributed to windows by
347	// the same epoch-aligned, left-closed rule Add uses: the first bucket
348	// returned is the one containing from, and a bucket starting exactly at
349	// to is excluded. An interval whose end does not come after its start
350	// yields an empty slice, as does an interval no bucket overlaps. The
351	// result is a snapshot of one moment: samples filed after the call do
352	// not alter it.
353	func (r *Roller) Range(from, to time.Time) []Window {
354		r.mu.RLock()
355		defer r.mu.RUnlock()
356		out := []Window{}
357		if !from.Before(to) {
358			return out
359		}
360		lo := r.startOf(from)
361		i, _ := windowIndex(r.buckets, lo)
362		j, _ := windowIndex(r.back, lo)
363		for {
364			var w Window
365			switch {
366			case i < len(r.buckets) && (j >= len(r.back) || r.buckets[i].Start.Before(r.back[j].Start)):
367				w = r.buckets[i]
368				i++
369			case j < len(r.back):
370				w = r.back[j]
371				j++
372			default:
373				return out
374			}
375			if !w.Start.Before(to) {
376				return out
377			}
378			out = append(out, w)
379		}
380	}
381	
382	// Cursor reads a fixed range of windows in batches. The windows are
383	// snapshot when the cursor is created: samples filed, backfilled, or
384	// merged in afterwards do not alter what the cursor returns, so batched
385	// iteration over a large range never tears, skips, or repeats a window,
386	// and the end of the range is reached deterministically no matter what
387	// is written while the cursor advances.
388	//
389	// A Cursor is safe to advance from multiple goroutines at once; each
390	// batch is handed out exactly once.
391	type Cursor struct {
392		// mu guards pos. windows is fixed at creation and read without the
393		// lock.
394		mu      sync.Mutex
395		windows []Window
396		pos     int
397	}
398	
399	// Cursor returns a cursor over the buckets overlapping the half-open
400	// interval [from, to), selected by the same rule as Range.
401	func (r *Roller) Cursor(from, to time.Time) *Cursor {
402		return &Cursor{windows: r.Range(from, to)}
403	}
404	
405	// Next returns the next batch of up to n windows, in time order. Batches
406	// are consecutive and non-overlapping: together they cover exactly the
407	// windows in the cursor's range. Once the range is exhausted, Next
408	// returns an empty slice and the cursor does not move. A non-positive n
409	// yields an empty slice and does not advance the cursor.
410	func (c *Cursor) Next(n int) []Window {
411		c.mu.Lock()
412		defer c.mu.Unlock()
413		rest := len(c.windows) - c.pos
414		if n <= 0 || rest == 0 {
415			return []Window{}
416		}
417		if n > rest {
418			n = rest
419		}
420		out := make([]Window, n)
421		copy(out, c.windows[c.pos:c.pos+n])
422		c.pos += n
423		return out
424	}
425	
426	// Merge folds other's buckets into this roller: counts and sums add,
427	// minimums take the smaller, maximums take the larger, and buckets only one
428	// side has are carried over as-is. Merging does not affect out-of-order
429	// tracking. It panics with "rollup: nil roller" if other is nil, and
430	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
431	// sizes differ.
432	//
433	// The merge is atomic with respect to every other call on either roller:
434	// concurrent readers see this roller wholly before or wholly after the
435	// merge, and a sample filed into other while the merge runs is either
436	// folded in completely or not at all. If the two rollers merge each other
437	// at the same time, the outcome matches some serial order of the two
438	// merges; neither is lost.
439	func (r *Roller) Merge(other *Roller) error {
440		if other == nil {
441			panic("rollup: nil roller")
442		}
443		if other.window != r.window {
444			return ErrWindowMismatch
445		}
446		if r == other {
447			r.mu.Lock()
448			defer r.mu.Unlock()
449			for _, buckets := range [][]Window{r.buckets, r.back} {
450				for i := range buckets {
451					w := &buckets[i]
452					w.Count = satAdd(w.Count, w.Count)
453					w.Sum += w.Sum
454				}
455			}
456			return nil
457		}
458		// Lock both rollers in ID order so simultaneous merges in
459		// opposite directions cannot deadlock.
460		first, second := r, other
461		if other.id < r.id {
462			first, second = other, r
463		}
464		first.mu.Lock()
465		second.mu.Lock()
466		defer second.mu.Unlock()
467		defer first.mu.Unlock()
468	
469		switch {
470		case len(other.buckets) == 0 && len(other.back) == 0:
471			return nil
472		case len(r.buckets) == 0 && len(r.back) == 0:
473			r.buckets = mergeWindows(other.buckets, other.back)
474			return nil
475		}
476		left, right := r.buckets, other.buckets
477		if len(r.back) != 0 {
478			left = mergeWindows(r.buckets, r.back)
479		}
480		if len(other.back) != 0 {
481			right = mergeWindows(other.buckets, other.back)
482		}
483		// Both sides are sorted by window start, so the merge is one linear
484		// pass and one backing array, no per-bucket copies or lookups.
485		r.buckets = mergeWindows(left, right)
486		r.back = nil
487		return nil
488	}
489	
490	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
491	func satAdd(a, b int64) int64 {
492		if b > math.MaxInt64-a {
493			return math.MaxInt64
494		}
495		return a + b
496	}
